import Cookies from 'js-cookie';


function SendMessage( message ) {

  const csrftoken = Cookies.get('csrftoken');
  const URL = 'input/message/';

  const request = new Request( URL, {
    method: 'POST',
    credentials: 'same-origin',
    headers:{
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-Requested-With': 'XMLHttpRequest',
      'X-CSRFToken': csrftoken,
  },
    body: JSON.stringify({data: message})
  });

  fetch( request )
  //.then( response => {console.log("Response about message : " + message);console.log(response)} )
  .catch( err => {console.log("Error Occured :");console.log(err)} );
}



function SendFile( file ) {

  const csrftoken = Cookies.get('csrftoken');
  const URL = 'input/file/';

  const request = new Request( URL, {
    method: 'POST',
    credentials: 'same-origin',
    headers:{
      'X-Requested-With': 'XMLHttpRequest',
      'X-CSRFToken': csrftoken,
  },
    body: file
  });

  fetch( request )
  //.then( response => {console.log("Response about file : " + file);console.log(response);} )
  .catch( err => {console.log("Error Occured :");console.log(err)} );
}




export {
  SendMessage,
  SendFile,
};
