import styles from "@chatscope/chat-ui-kit-styles/dist/default/styles.min.css";
import {
  MainContainer,
  ChatContainer,
  MessageList,
  MessageInput,

  InputToolbox,
  AttachmentButton,
  SendButton,
  InfoButton,

  MessageSeparator, 
  Loader
} from "@chatscope/chat-ui-kit-react";

//import Popup from 'reactjs-popup';
import AnnouncementModal from './AnnouncementModal';

import { useState, useRef, useEffect } from 'react';


// left
import ProcessConversationList from './left/ProcessConversationList';
// middle
import ProcessChatlog from './middle/ProcessChatlog';
// right
import ProcessSidebar from './right/ProcessSidebar';

// send Message or File to Server
import { SendMessage, SendFile } from './SendData';



function ChatUi() {

  function ButtonsForMobile() {
    // ~ 576 : no buttons at all
    // ~ 768 : chatroom buttons only but without roomname

    //console.log("Attach ButtonsForMobile: Width: "+window.innerWidth)

    if ( window.innerWidth < 576 ) {
      return (
        <AnnouncementModal />
      )
    } else if ( window.innerWidth < 768 ) {
      return (
        <AnnouncementModal />
      )
    }
  }

  // 아래 메세지 입력 창 state
  const [ msgInputValue, setMsgInputValue ] = useState("");

  // 이미지 업로드용 html input element Reference
  const imgUpRef = useRef();

  function HandleMsgSend(message) {
    SendMessage(message);
    setMsgInputValue("");
  }

  function HandleFileChange(event) {
    //console.log("DataChange")
    HandleFileSend(event)
  }

  function HandleFileSend(event) {

    const formdata = new FormData();

    formdata.append("file", event.target.files[0])

    SendFile(formdata)

    event.target.value = null

  };



  return (
    <div style={{ position: "fixed", height: "100%", width: "100%" }}>

      <MainContainer responsive={true}>

        <ProcessConversationList />

        <ChatContainer>

          <MessageList>

            <br />
            {
              (!( global.config.django.fetchfailed < global.config.django.ALLOW_FETCH_FAILURE ))
                ? <Loader style={{marginLeft: '40%'}}> Connection Failed </Loader>
                : null
            }
            <ProcessChatlog />

          </MessageList>

          <MessageInput 
            fancyScroll={false} 
            placeholder="Your message here" 
            sendButton={true} 
            attachButton={false} 
            autoFocus={true} 
            onChange={setMsgInputValue} 
            value={msgInputValue} 
            onSend={HandleMsgSend}
          />
          <InputToolbox>

            <input type="file" id="imgUpload" style={{display: "none"}} ref={imgUpRef} 
              onChange={ HandleFileChange }
            />

            { ButtonsForMobile() }
            <AttachmentButton 
              onClick={ () => { imgUpRef.current.click(); } } 
            />

          </InputToolbox>

        </ChatContainer>

        <ProcessSidebar />

      </MainContainer>
    </div>
  );
}

export default ChatUi;
