import Popup from 'reactjs-popup';

import './assets/defaults/css/bootstrap/bootstrap.min.css';
import 'devextreme/dist/css/dx.light.css';
 
import { ScrollView } from 'devextreme-react/scroll-view';

import { InfoButton } from "@chatscope/chat-ui-kit-react"

import { useState, useEffect } from 'react';


function AnnouncementModal() {

  const url = 'announcement/data.json';

  const [ title, setTitle ] = useState('');
  const [ anncm, setAnncm ] = useState([]);

  useEffect( ()=> {
    fetch(url, {
      headers: { 
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      }
    })
    .then( response => response.json() )
    .then( jsonRoomdata => {
      setTitle(jsonRoomdata.announcement_title);
      setAnncm(jsonRoomdata.announcement);
    });
  }, []);

  return(
    <Popup trigger={<InfoButton />} modal nested >

      {close => (
        <ScrollView 
          height="90vh"
          width="95vw"
          direction="vertical"
        >
          <div className="modal-dialog modal-lg" role="document" tabIndex="-1">

            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title" id="exampleModalLongTitle">
                  {title}
                </h5>
                <button 
                  type="button" 
                  className="close" 
                  data-dismiss="modal" 
                  aria-label="Close" 
                  onClick={() => {
                    //console.log('modal closed ');
                    close();
                  }} 
                >
                  <span aria-hidden="true">&times;</span>
                </button>
              </div>

              <div className="modal-body">
                {anncm.map( (item) => {
                  return(
                    <p>{item}</p>
                  )
                })}
              </div>

              <div className="modal-footer">
                <button
                  type="button" 
                  className="btn btn-lg btn-secondary" 
                  data-dismiss="modal" 
                  onClick={() => {
                    //console.log('modal closed ');
                    close();
                  }}
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        </ScrollView>
      )}

    </Popup>
  );
}

export default AnnouncementModal;
