import styles from "@chatscope/chat-ui-kit-styles/dist/default/styles.min.css";

import { Sidebar, ExpansionPanel, } from "@chatscope/chat-ui-kit-react";



function SidebarBox(props) {

  let content = [];
  
  for (let i = 0; i < props.textArray.length; i++) {
    content.push(
      <p key={i}>{
        props.textArray[i] 
        ? props.textArray[i] 
        : <br />
      }</p>
    );
  }


  return (
	<Sidebar position="right">
    <ExpansionPanel open title={props.roomname}>
      <h4>{props.title}</h4>
      <br />
      {content}
    </ExpansionPanel>
  </Sidebar>
  );
}

export default SidebarBox;