import styles from "@chatscope/chat-ui-kit-styles/dist/default/styles.min.css";

import { Avatar, Conversation, } from "@chatscope/chat-ui-kit-react";

import defaultChatRoomIcon from './../assets/defaults/png/chatRoomIcon.png';
//import { redirect } from "react-router-dom";



function ConversationBox(props) {

  return (
    <Conversation 
      onClick={ () => { 
        window.location.href = ("/chat/home/" + props.roomid + '/'); 
      } } 
      name={props.targetName} 
      info={props.lastMsg} 
    >
      <Avatar 
        src={ (props.avatarSrc)? props.avatarSrc : defaultChatRoomIcon } 
        name={props.targetName} 
      />
    </Conversation>
  );
}


export default ConversationBox;