import {
  Sidebar, 
  Search, 
  ConversationList, 
  Conversation, 
} from "@chatscope/chat-ui-kit-react";

import ConversationBox from './ConversationBox';

import { useState, useEffect } from 'react';



function ProcessConversationList() {

  const url = 'room/data.json';

  const [ roomdata, setRoomdata ] = useState([]);

  useEffect( ()=> {
    fetch(url, {
      headers: { 
        'Content-Type': 'application/json',
        'Accept': 'application/json',
      }
    })
    .then( response => response.json() )
    .then( jsonRoomdata => {
      //console.log(jsonRoomdata);
      setRoomdata(jsonRoomdata);
    });
  }, [url]);


  return (
    <Sidebar position="left" scrollable={false}>

      <form method="POST">
        <Search id="chatroom_search" placeholder="Search..." />
      </form>

      <ConversationList>

        {roomdata && roomdata.length > 0 && roomdata.map( (item) => { 
          //console.log('curr at return, PK = ' + item.id);
          return(
            <ConversationBox
              roomid={item.id}
              targetName={item.roomname}
              lastMsg={item.announcement_title}
            />
          );
        })}

      </ConversationList>

    </Sidebar>
  );
}

export default ProcessConversationList;
