import { Message, Avatar, } from "@chatscope/chat-ui-kit-react";
import defaultUserIcon from './../assets/defaults/png/singleUserIcon.png';
import blankImage from './../assets/defaults/png/blankImage.png';



function ImageBox(props) {

  function RenderFullsizeImage(event) {
    // rel='noreferrer' to not sending any information to new tab from current tab
    // but, now we are forwarding to child page, and needs 'request.user' information
    window.open('media/filecontent/' + props.imageSrc, '_blank')
  }

  const windowRatio = ( window.innerWidth / window.innerHeight );

  const maxAcceptableFromHeight = ( windowRatio * ( window.innerHeight * 0.15 ) );

  const maxAcceptableFromWidth = ( windowRatio * ( window.innerWidth * 0.80 ) );

  const imageWidth = Math.max( Math.min( maxAcceptableFromWidth, maxAcceptableFromHeight ), 160 );

  //console.log("\r\n")
  //console.log("maxAcceptableFromHeight: "+maxAcceptableFromHeight)
  //console.log("maxAcceptableFromWidth: "+maxAcceptableFromWidth)
  //console.log("imageWidth: "+imageWidth)

  if ( props.fromSelf ) {

    return (
      <Message model={{
        message: "",
        direction: "outgoing",
        position: "single"
      }} onClick={ (event) => { RenderFullsizeImage(event) } } >
        <Message.Footer 
          sender={props.username} 
          sentTime={ 
            !props.sameuser
              ? props.sentTime 
              : undefined
          } 
        />
        {
          !props.sameuser
            ? <Avatar avatarPosition="top-left" src={ props.avatarSrc ? props.avatarSrc : defaultUserIcon } />
            : <Avatar avatarPosition="top-left" src={ blankImage } />
        }
        <Message.ImageContent 
          src={'media/filecontent/' + props.imageSrc} 
          width={ imageWidth+"px" }
        />
      </Message>
    );

  } else {
    return (
      <Message model={{
        message: "",
      }} onClick={ (e) => { RenderFullsizeImage(e) } } >
        <Message.Footer 
          sender={ 
            !props.sameuser
              ? props.username 
              : undefined
          } 
          sentTime={ 
            !props.sameuser
              ? props.sentTime 
              : undefined
          } 
        />
        {
          !props.sameuser
            ? <Avatar avatarPosition="top-left" src={ props.avatarSrc ? props.avatarSrc : defaultUserIcon } />
            : <Avatar avatarPosition="top-left" src={ blankImage } />
        }
        <Message.ImageContent 
          src={'media/filecontent/' + props.imageSrc} 
          width={ imageWidth+"px" }
        />
      </Message>
    );
  }
}

export default ImageBox;
