import { useState, useEffect } from 'react';

import MessageBox from './MessageBox';
import ImageBox from './ImageBox';
import BuildSeparator from './BuildSeparator';

function BuildMessageBox(item) {
  return (
    <MessageBox
      fromSelf={item.fromSelf} 
      avatarSrc={ (item.avatarSrc)? item.avatarSrc : undefined } 
      username={item.username} 
      message={item.text_content} 
      sentTime={item.sentAt} 
      sameuser={item.sameuser}
    />
  );
}
function BuildImageBox(item) {
  return (
    <ImageBox
      fromSelf={item.fromSelf} 
      avatarSrc={ (item.avatarSrc)? item.avatarSrc : undefined } 
      username={item.username} 
      imageSrc={item.file_content} 
      sentTime={item.sentAt} 
      sameuser={item.sameuser}
    />
  );
}


function ProcessChatlog() {

  const url = 'chat/' + global.config.django.currpk + '/data.json';

  const [ logs, setLogs ] = useState([]);

  useEffect( () => {

    const fetchData = async () => {

      //console.log("Request Target : " + url);

      fetch(url, {
        headers: 
        { 
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        }
      })
      .then( (response) => {

        if (response?.ok) {
          //console.log('Fetch Success');
          global.config.django.fetchfailed = 0;
        }

        return response.json()
      })
      .then( (chatlogList) => { 
        setLogs( [...chatlogList, ...logs] )
      })
      .catch( (error) => {
        //console.log(error);
        global.config.django.fetchfailed += 1;
        //console.log('Fetch Failed = ' + global.config.django.fetchfailed);
      })
    };

    const interval = setInterval(() => {
      if ( global.config.django.fetchfailed < global.config.django.ALLOW_FETCH_FAILURE ) {
        fetchData();
      } else {
        //console.log("fetch failed more than ALLOW_FETCH_FAILURE, stop fetch")
      }
    }, 3000);

    return () => clearInterval(interval);
    

  }, [url]);
  
  return (
    logs && logs.length > 0 && logs.map( 
      (item) => { 
        global.config.django.currpk = Math.max(
          global.config.django.currpk,
          item.id
        )
        if (item.isText) {
          return( BuildMessageBox(item) )
        } else if (item.file_content === "<<<TYPE::SEPARATOR>>>") {
          return( BuildSeparator(item) )
        } else {
          return( BuildImageBox(item) )
        }
      }
    )
  );
}



export default ProcessChatlog;
