import { Message, Avatar, } from "@chatscope/chat-ui-kit-react";
import defaultUserIcon from './../assets/defaults/png/singleUserIcon.png';
import blankImage from './../assets/defaults/png/blankImage.png';


function MessageBox(props) {

  if ( props.fromSelf ) {
    return (
      <Message model={{
        message: props.message,
        direction: "outgoing",
        position: "single"
      }}>
        <Message.Footer 
          sender={props.username} 
          sentTime={ 
            !props.sameuser
              ? props.sentTime 
              : undefined
          } 
        />
        {
          !props.sameuser
            ? <Avatar avatarPosition="top-left" src={ props.avatarSrc ? props.avatarSrc : defaultUserIcon } />
            : <Avatar avatarPosition="top-left" src={ blankImage } />
        }
      </Message>
    );

  } else {
    return (
      <Message model={{
        message: props.message,
      }}>
        <Message.Footer 
          sender={
            !props.sameuser
              ? props.username 
              : undefined
          } 
          sentTime={ 
            !props.sameuser
              ? props.sentTime 
              : undefined
          } 
        />
        {
          !props.sameuser
            ? <Avatar avatarPosition="top-left" src={ props.avatarSrc ? props.avatarSrc : defaultUserIcon } />
            : <Avatar avatarPosition="top-left" src={ blankImage } />
        }
      </Message>
    );
  }
}

export default MessageBox;
